verify: { title: L.extVerT, text: L.extVerX, progress: true, warn: true, primaryLabel: L.extCont, primary: () => { this.setState({ ext: 'scanning' }); this.startScan(true); }, secondaryLabel: L.extStop, secondary: stop },
